using namespace std;using I=long long;
vector<int> inflate(vector<int>s,int r){vector<int>a(5+r);for(int i=0;i<5;i++){a[i]=s[i]&31;for(int v=5;v<5+r;v++)if(s[i]>>5&1)a[i]|=1<<v;else a[v]|=1<<i;}for(int u=5;u<5+r;u++)for(int v=u+1;v<5+r;v++)a[u]|=1<<v;return a;}
vector<int> rev(vector<int>a){for(int i=0;i<(int)a.size();i++)a[i]^=((1<<a.size())-1)^(1<<i);return a;}
I hp(vector<int>a){int n=a.size(),N=1<<n;vector<I>d(N*n);for(int i=0;i<n;i++)d[(1<<i)*n+i]=1;for(int m=1;m<N;m++)for(int bits=m;bits;bits&=bits-1){int u=__builtin_ctz(bits);I q=d[m*n+u];if(!q)continue;for(int b=a[u]&~m;b;b&=b-1){int v=__builtin_ctz(b);d[(m|(1<<v))*n+v]+=q;}}I h=0;for(int i=0;i<n;i++)h+=d[(N-1)*n+i];return h;}
I query(vector<int>a,int x,int y){int n=a.size();a.push_back(1<<(n+1));a.push_back(0);for(int i=0;i<n;i++){if(x>>i&1)a[i]|=1<<n;else a[n]|=1<<i;if(y>>i&1)a[i]|=1<<(n+1);else a[n+1]|=1<<i;}return hp(a);}
void vec(vector<int>a){cout<<'[';bool first=true;for(int x:a){if(!first)cout<<',';first=false;cout<<x;}cout<<']';}
int main(){vector<vector<int>>ss={{16,5,33,39,46,3},{16,5,49,39,42,3},{18,4,49,39,42,3}};cout<<"{\"status\":\"PASS\",\"cases\":[";bool first=true;for(int r=1;r<=7;r++)for(int j=0;j<3;j++){auto a=inflate(ss[j],r);int n=a.size();vector<int>ms;for(int m=0;m<(1<<n);m++)if(__builtin_popcount((unsigned)m)<=2)ms.push_back(m);int sz=ms.size();vector<I>base(sz*sz);for(int u=0;u<sz;u++)for(int v=0;v<sz;v++)base[u*sz+v]=query(a,ms[u],ms[v]);for(int mode=0;mode<2;mode++){if(mode&&r==1)continue;auto b=mode?a:rev(a);if(mode){b[5]^=1<<6;b[6]^=1<<5;}if(!first)cout<<',';first=false;cout<<"{\"r\":"<<r<<",\"state\":"<<j<<",\"kind\":\""<<(mode?"pair_reversal":"global_converse")<<"\",\"rows\":";vec(a);cout<<",\"other_rows\":";vec(b);cout<<",\"battery_masks\":";vec(ms);vector<I>d(sz*sz),co(sz*sz);vector<int>ix(1<<n,-1);for(int u=0;u<sz;u++)ix[ms[u]]=u;cout<<",\"battery\":[";for(int u=0;u<sz;u++)for(int v=0;v<sz;v++){I h=query(b,ms[u],ms[v]);d[u*sz+v]=base[u*sz+v]-h;if(u||v)cout<<',';cout<<'['<<base[u*sz+v]<<','<<h<<']';}cout<<"],\"coefficients\":[";bool cf=true;int degree=0;for(int u=0;u<sz;u++)for(int v=0;v<sz;v++){int x=ms[u],y=ms[v];I z=0;for(int xx=x;;xx=(xx-1)&x){for(int yy=y;;yy=(yy-1)&y){int parity=__builtin_popcount((unsigned)(x^xx))+__builtin_popcount((unsigned)(y^yy));z+=(parity&1?-1:1)*d[ix[xx]*sz+ix[yy]];if(!yy)break;}if(!xx)break;}co[u*sz+v]=z;if(z){int deg=__builtin_popcount((unsigned)x)+__builtin_popcount((unsigned)y);degree=max(degree,deg);if(!mode&&(deg>3||((x==0||y==0)&&deg==2)))throw runtime_error("cubic violated");if(!cf)cout<<',';cf=false;cout<<'['<<x<<','<<y<<','<<z<<']';}}
cout<<"],\"degree\":"<<degree<<",\"dense_controls\":[";vector<pair<int,int>>controls={{(1<<n)-1,(1<<n)-1},{(1<<n)-1,0},{0,(1<<n)-1},{0x555&((1<<n)-1),0x333&((1<<n)-1)}};bool dc=true;for(auto [x,y]:controls){I expected=query(a,x,y)-query(b,x,y),actual=0;for(int u=0;u<sz;u++)for(int v=0;v<sz;v++)if((ms[u]&x)==ms[u]&&(ms[v]&y)==ms[v])actual+=co[u*sz+v];if(expected!=actual)throw runtime_error("interpolation mismatch");if(!dc)cout<<',';dc=false;cout<<'['<<x<<','<<y<<','<<expected<<']';}cout<<"]}";cerr<<"done r="<<r<<" j="<<j<<" mode="<<mode<<" degree="<<degree<<'\n';}}
cout<<"]}\n";}
